export default()=>{const e=[],t=document.querySelectorAll("h1");e.push({icon:1===t.length?"green":"red",title:"H1 Check",description:1===t.length?"Good: One H1 found":`Error: Found ${t.length} H1 tags`});const o=document.title.replace(/\s/g,"").length;e.push({icon:o>=15&&o<=70?"green":"red",title:"Title Length",description:o>=15&&o<=70?"Good: Title length is optimal":"Error: Title should be 15-70 characters"});const n=document.querySelector('meta[name="description"]'),r=n?.content.replace(/\s/g,"").length||0;e.push({icon:r>=50&&r<=150?"green":"red",title:"Meta Description",description:r>=50&&r<=150?"Good: Meta description length is optimal":"Error: Meta description should be 50-150 characters"});const i=document.body.textContent.replace(/\s+/g," ").trim(),s=i.split(" ").length;e.push({icon:s>=300?"green":"red",title:"Content Length",description:s>=300?`Good: Content length (${s} words)`:`Warning: Content length (${s} words) is less than recommended 300 words`});const c=i.toLowerCase().includes("lorem ipsum");return e.push({icon:c?"red":"green",title:"Lorem Ipsum Check",description:c?"Error: Lorem Ipsum text detected":"Good: No Lorem Ipsum found"}),e};